'use strict';
// Practice state is isolated from community points and badges.
state.review=state.review||{track:null,session:null,history:[],records:{},flagged:[]};
const reviewIndex=new Map(reviewBanks.flatMap(b=>b.questions.map(q=>[q.id,q])));
let reviewSetPage=0,reviewFilter='',reviewReadIndex=0,reviewReveal=false,reviewReadSet=null;
const renderBeforeReview=render,renderNavBeforeReview=renderNav,navBeforeReview=nav;
function reviewBank(){return reviewBanks.find(b=>b.id===state.review.track)}
function reviewCommit(change){const previous=JSON.stringify(state.review);change();if(!persist()){state.review=JSON.parse(previous);return false}return true}
function reviewScore(s){return s.ids.reduce((n,id)=>n+(s.answers[id]===reviewIndex.get(id)?.answer?1:0),0)}
function reviewSets(b){return [...new Set(b.questions.map(q=>q.set))].map(set=>({set,questions:b.questions.filter(q=>q.set===set)}))}
function reviewPool(set){return reviewBank().questions.filter(q=>(!set||q.set===Number(set))&&!state.review.flagged.includes(q.id))}
function beginReview(set,kind='practice'){
 const b=reviewBank();if(!b)return false;
 let pool=reviewPool(set);if(kind==='mistakes')pool=pool.filter(q=>state.review.records[q.id]?.correct===false);
 if(!pool.length){toast('No questions available for this selection.');return false}
 // Shuffle within mastery levels, favoring unseen and missed material.
 pool=pool.map(q=>({q,order:Math.random(),level:state.review.records[q.id]?.correct?1:0})).sort((a,b)=>a.level-b.level||a.order-b.order).map(x=>x.q);
 if(!reviewCommit(()=>{state.review.session={track:b.id,set:Number(set)||null,kind,ids:pool.slice(0,10).map(q=>q.id),index:0,answers:{},choice:null,done:false}}))return false;
 reviewReadSet=null;render();window.scrollTo(0,0);return true;
}
function chooseReview(option){const s=state.review.session;if(!s||s.done||s.answers[s.ids[s.index]]!==undefined||![0,1,2,3].includes(option))return false;return reviewCommit(()=>{s.choice=option})}
function checkReview(){const s=state.review.session;if(!s||s.done||s.choice===null||s.answers[s.ids[s.index]]!==undefined)return false;const id=s.ids[s.index],q=reviewIndex.get(id);if(!q)return false;return reviewCommit(()=>{s.answers[id]=s.choice;const old=state.review.records[id];state.review.records[id]={attempts:(old?.attempts||0)+1,correct:s.choice===q.answer};s.choice=null})}
function nextReview(){const s=state.review.session;if(!s||s.done||s.answers[s.ids[s.index]]===undefined)return false;return reviewCommit(()=>{if(s.index+1<s.ids.length){s.index++;s.choice=null}else{s.done=true;state.review.history.unshift({track:s.track,set:s.set,score:reviewScore(s),total:s.ids.length,date:new Date().toISOString()});state.review.history=state.review.history.slice(0,30)}})}
function reviewSource(q){return `<a class="review-source" href="assets/review/${state.review.track}.pdf#page=${q.page}" target="_blank" rel="noopener">Source Q${q.number} · PDF page ${q.pages.join('–')} ↗</a>`}
function reviewHeader(){return `<div class="eyebrow">OPTIONAL / PERSONAL PRACTICE</div><h1 class="page-title">A little review.<br>A stronger next watch.</h1><p class="subtitle">Short rounds. One question at a time. Keep learning at your own pace.</p>`}
function reviewLanding(){app.innerHTML=reviewHeader()+`<div class="review-track-grid">${reviewBanks.map(b=>`<button class="review-track" data-review-track="${b.id}"><span class="review-track-icon">${b.id==='nw'?'◈':'⚙'}</span><strong>${b.title}</strong><span>${b.subtitle}</span><small>${b.questions.length.toLocaleString()} practice questions · ${reviewSets(b).length} sets</small><b>Choose this reviewer →</b></button>`).join('')}</div><div class="note"><strong>Your Q&A hub stays at the center.</strong> Review is an optional practice space. Scores stay in this browser and do not affect the contributor leaderboard.</div><details class="review-notes"><summary>About these reviewers and answer keys</summary><p>Practice is based on the PDFs supplied by JV. Their marked answers still need verification. This is not an official MARINA exam or a qualification.</p><p>Practice sets follow source question numbers, in blocks of 50. These are study divisions, not official competency mappings. Each question links to its source page.</p></details>`}
function reviewTrackView(){const b=reviewBank();if(!b){reviewLanding();return}const r=state.review;const records=b.questions.filter(q=>r.records[q.id]);const correct=records.filter(q=>r.records[q.id].correct).length;const missed=records.length-correct;const history=r.history.filter(h=>h.track===b.id);const sets=reviewSets(b).filter(s=>!reviewFilter||s.questions.some(q=>(q.question+' '+q.number).toLowerCase().includes(reviewFilter.toLowerCase())));const visible=sets.slice(reviewSetPage*8,reviewSetPage*8+8);app.innerHTML=`<button class="back" data-review-action="tracks">← Choose another reviewer</button><header class="review-track-heading"><div><div class="eyebrow">${b.subtitle.toUpperCase()}</div><h1 class="page-title">${b.title} review</h1><p class="subtitle">Choose a practice set, or take a mixed round.</p></div><span class="review-track-icon">${b.id==='nw'?'◈':'⚙'}</span></header><section class="review-journey card"><span class="eyebrow">YOUR PRACTICE JOURNEY</span><h2>${correct} <small>/ ${b.questions.length.toLocaleString()} answered correctly on the latest attempt</small></h2><progress value="${correct}" max="${b.questions.length}" aria-label="Questions answered correctly on latest attempt"></progress><p>${records.length} questions tried · ${history.length} recent rounds saved · ${missed} to revisit</p><div class="review-actions">${r.session?.track===b.id&&!r.session.done?'<button class="btn" data-review-action="resume">Continue your round →</button>':'<button class="btn" data-review-start="all">Start 10-question mix →</button>'}<button class="btn quiet" data-review-action="mistakes" ${missed?'':'disabled'}>Practice mistakes · ${missed}</button></div></section><h2 class="review-section-title">Your practice sets</h2><p class="hint">Source order · up to 50 questions per set · short rounds of up to 10. Sets are not official competency groups.</p><label class="search">${icon('search')}<input id="reviewSearch" type="search" value="${esc(reviewFilter)}" placeholder="Find sets by word or question number…" aria-label="Find practice sets"></label><div class="review-sets">${visible.map(s=>{const correct=s.questions.filter(q=>r.records[q.id]?.correct).length;return `<article class="card review-set"><div><span class="eyebrow">SET ${String(s.set).padStart(2,'0')}</span><h3>Questions ${(s.set-1)*50+1}–${Math.min(s.set*50,Math.max(...b.questions.map(q=>q.number)))}</h3><p>${s.questions.length} available · ${correct} correct on latest attempt</p></div><progress max="${s.questions.length}" value="${correct}" aria-label="Set ${s.set} progress"></progress><div class="review-actions"><button class="btn" data-review-start="${s.set}">Practice →</button><button class="text-button" data-review-read="${s.set}">Read answers</button></div></article>`}).join('')||'<p>No matching sets. Try another word.</p>'}</div><div class="review-pagination"><button class="btn quiet" data-review-action="previousSets" ${reviewSetPage?'':'disabled'}>← Previous</button><span>${sets.length?'Page '+(reviewSetPage+1)+' of '+Math.ceil(sets.length/8):'No sets'}</span><button class="btn quiet" data-review-action="nextSets" ${(reviewSetPage+1)*8<sets.length?'':'disabled'}>Next →</button></div>${history.length?`<details class="review-notes"><summary>Recent practice results</summary>${history.slice(0,10).map(h=>`<p><strong>${h.score}/${h.total}</strong> · ${h.set?'Set '+h.set:'Mixed practice'} · ${new Date(h.date).toLocaleDateString()}</p>`).join('')}</details>`:''}<p class="hint">${r.flagged.filter(id=>id.startsWith(b.id+'-')).length} questions flagged by you are skipped in future scored rounds. <button class="text-button" data-review-action="clearFlags">Clear flags</button></p><p class="hint">Source markings are provisional. Consult current approved references when an answer seems questionable.</p>`;document.querySelector('#reviewSearch').oninput=e=>{reviewFilter=e.target.value;reviewSetPage=0;const input=e.target;const start=input.selectionStart;reviewTrackView();const next=document.querySelector('#reviewSearch');next.focus();next.setSelectionRange?.(start,start)}}
function reviewQuestionView(){const s=state.review.session,q=reviewIndex.get(s?.ids[s.index]);if(!q){reviewTrackView();return}if(s.done){reviewResultView();return}const checked=s.answers[q.id]!==undefined;const chosen=checked?s.answers[q.id]:s.choice;app.innerHTML=`<button class="back" data-review-action="sets">← Pause & return to sets</button><div class="review-round-meta"><strong>${reviewBank().title} · ${s.kind==='mistakes'?'Mistake practice':s.set?'Set '+s.set:'Mixed round'}</strong><span>${s.index+1} / ${s.ids.length}</span></div><progress class="review-round-progress" value="${s.index+(checked?1:0)}" max="${s.ids.length}" aria-label="Round progress"></progress><article class="card review-question"><span class="eyebrow">QUESTION ${q.number}</span><h1 id="reviewPrompt">${esc(q.question)}</h1><div class="review-options" role="group" aria-labelledby="reviewPrompt">${q.options.map((text,i)=>`<button class="review-option ${chosen===i?'selected':''} ${checked&&i===q.answer?'correct':''} ${checked&&chosen===i&&i!==q.answer?'incorrect':''}" data-review-choice="${i}" aria-pressed="${chosen===i}" ${checked?'disabled':''}><b>${'ABCD'[i]}</b><span>${esc(text)}</span>${checked&&i===q.answer?'<strong aria-label="Marked answer">✓</strong>':''}</button>`).join('')}</div>${checked?`<section class="review-feedback ${chosen===q.answer?'right':'retry'}" role="status"><h2>${chosen===q.answer?'You matched the source answer.':'Keep going—you can revisit this.'}</h2><p><strong>Reviewer’s marked answer: ${'ABCD'[q.answer]}.</strong> ${esc(q.options[q.answer])}</p><p>Marked in the supplied reviewer. Check the source if an answer seems questionable.</p></section>`:'<p class="hint">Choose one answer, then check it. No timer or lost lives.</p>'}<div class="review-actions">${checked?`<button class="btn" data-review-action="next">${s.index+1===s.ids.length?'See my score':'Next question'} →</button>`:`<button class="btn" data-review-action="check" ${chosen===null?'disabled':''}>Check answer</button>`}</div><div class="review-question-foot">${reviewSource(q)}<button class="text-button" data-review-action="flag" ${state.review.flagged.includes(q.id)?'disabled':''}>${state.review.flagged.includes(q.id)?'Flagged locally':'Flag an issue'}</button></div><p class="hint">Flagging skips this question in future rounds on this browser. It does not send a report to JV yet.</p></article>`}
function reviewResultView(){const s=state.review.session;if(!s)return reviewTrackView();const score=reviewScore(s);app.innerHTML=`<section class="card review-result"><img src="assets/seafarer-mascot.webp" alt="Seafarer mascot giving a thumbs-up"><div class="eyebrow">ROUND COMPLETE</div><h1>${score===s.ids.length?'A clean sweep!':'One round stronger.'}</h1><div class="review-score">${score}<small> / ${s.ids.length}</small></div><p>Answers matching the reviewer’s marked key</p><p class="hint">${s.ids.length-score?'Your missed questions are ready to revisit.':'Keep building the habit, one short round at a time.'} Practice scores do not add contributor points.</p><div class="review-actions"><button class="btn" data-review-action="sets">Back to practice sets →</button><button class="btn quiet" data-review-action="mistakes">Practice mistakes</button></div></section><h2 class="review-section-title">Your round, at a glance</h2>${s.ids.map(id=>{const q=reviewIndex.get(id);return `<details class="card review-recap"><summary>${s.answers[id]===q.answer?'✓':'↻'} Q${q.number} · ${esc(q.question)}</summary><p>Your answer: <strong>${esc(q.options[s.answers[id]])}</strong></p><p>Source answer: <strong>${esc(q.options[q.answer])}</strong></p>${reviewSource(q)}</details>`}).join('')}`}
function reviewReaderView(){const b=reviewBank(),qs=b.questions.filter(q=>q.set===reviewReadSet);reviewReadIndex=Math.max(0,Math.min(reviewReadIndex,qs.length-1));const q=qs[reviewReadIndex];if(!q)return reviewTrackView();app.innerHTML=`<button class="back" data-review-action="sets">← Practice sets</button><div class="review-round-meta"><strong>Read answers · ${b.title} · Set ${reviewReadSet}</strong><span>${reviewReadIndex+1}/${qs.length}</span></div><article class="card review-question"><span class="eyebrow">UNSCORED READING / Q${q.number}</span><h1>${esc(q.question)}</h1><ol type="A" class="review-read-options">${q.options.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>${reviewReveal?`<div class="review-feedback"><strong>Reviewer’s marked answer: ${'ABCD'[q.answer]}</strong><p>${esc(q.options[q.answer])}</p><small>Follows the supplied PDF; not independently validated.</small></div>`:'<button class="btn" data-review-action="reveal">Show source answer</button>'}${reviewSource(q)}</article><div class="review-pagination"><button class="btn quiet" data-review-action="readPrevious" ${reviewReadIndex?'':'disabled'}>← Previous</button><button class="btn" data-review-action="readNext" ${reviewReadIndex+1<qs.length?'':'disabled'}>Next →</button></div>`}
let reviewScreen='sets',lastReviewFrame='';
function animateReviewFrame(){const s=state.review.session;const key=[state.review.track,reviewScreen,reviewReadSet,reviewReadIndex,reviewScreen==='round'?s?.index:'',reviewScreen==='round'?s?.done:''].join(':');if(key===lastReviewFrame)return;lastReviewFrame=key;if(typeof app.animate==='function'&&!window.matchMedia('(prefers-reduced-motion: reduce)').matches)app.animate([{opacity:.5,transform:'translateX(12px)'},{opacity:1,transform:'translateX(0)'}],{duration:190,easing:'ease-out'})}
function reviewView(){if(!reviewBank())reviewLanding();else if(reviewReadSet)reviewReaderView();else if(reviewScreen==='round'&&state.review.session?.track===state.review.track)reviewQuestionView();else reviewTrackView()}
renderNav=function(){renderNavBeforeReview();const tabs=[['home','ask','Contribute'],['learn','learn','Library'],['review','review','Review'],['progress','explore','Progress'],['profile','profile','Profile']];for(const id of ['desktopNav','mobileNav'])document.getElementById(id).innerHTML=tabs.map(([p,i,label])=>`<button data-nav="${p}" class="${page===p||p==='progress'&&page==='leaderboard'?'active':''}" ${page===p||p==='progress'&&page==='leaderboard'?'aria-current="page"':''}>${i==='review'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="4" y="3" width="16" height="18" rx="3"/><path d="m8 12 3 3 5-6"/></svg>':icon(i)}<span>${label}</span></button>`).join('')};
nav=function(p){if(p==='review'&&state.hubOnboardingCompleted){page='review';selected=null;render();window.scrollTo(0,0);return}navBeforeReview(p)};
render=function(){if(page!=='review'||!state.hubOnboardingCompleted){renderBeforeReview();return}applyTheme();document.body.classList.remove('intro-mode');app.classList.remove('setup-view');renderNav();document.querySelector('#sectionName').textContent='Personal review';reviewView();animateReviewFrame();animatePolishedRoute();saveLastView()};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(d.reviewTrack){if(reviewCommit(()=>{state.review.track=d.reviewTrack})){reviewScreen='sets';reviewReadSet=null;reviewSetPage=0;reviewFilter='';render()}}if(d.reviewStart){reviewScreen='round';beginReview(d.reviewStart==='all'?null:Number(d.reviewStart))}if(d.reviewChoice!==undefined){if(chooseReview(Number(d.reviewChoice)))render()}if(d.reviewRead){reviewReadSet=Number(d.reviewRead);reviewReadIndex=0;reviewReveal=false;render()}if(!d.reviewAction)return;switch(d.reviewAction){case'tracks':if(!reviewCommit(()=>{state.review.track=null}))return;reviewReadSet=null;break;case'sets':reviewScreen='sets';reviewReadSet=null;break;case'resume':reviewScreen='round';break;case'mistakes':reviewScreen='round';beginReview(null,'mistakes');return;case'check':checkReview();break;case'next':nextReview();break;case'previousSets':reviewSetPage=Math.max(0,reviewSetPage-1);break;case'nextSets':reviewSetPage++;break;case'reveal':reviewReveal=true;break;case'readPrevious':reviewReadIndex--;reviewReveal=false;break;case'readNext':reviewReadIndex++;reviewReveal=false;break;case'flag':{const id=state.review.session?.ids[state.review.session.index];if(id&&!state.review.flagged.includes(id))reviewCommit(()=>state.review.flagged.push(id));break}case'clearFlags':reviewCommit(()=>{state.review.flagged=state.review.flagged.filter(id=>!id.startsWith(state.review.track+'-'))});break}render();if(!['check','reveal','flag'].includes(d.reviewAction))window.scrollTo(0,0)});
render();
